  MoladImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  MoladImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_Molad,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_Molad,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_MoladPtr,
  );

  /// The *chalakim* past the minute, from 0 to 17. A *chelek* is 1/1080 of an hour, or 3⅓
  /// seconds.
  int get chalakim => RustLib.instance.api
      .kosherRustCalendarMoladFrbOverrideChalakim(that: this);

  /// The hour, from 0 to 23.
  int get hours =>
      RustLib.instance.api.kosherRustCalendarMoladFrbOverrideHours(that: this);

  /// The minutes past the hour, from 0 to 59.
  int get minutes => RustLib.instance.api
      .kosherRustCalendarMoladFrbOverrideMinutes(that: this);

  /// The moment of the molad, converted from Jerusalem mean time, in seconds since the Unix
  /// epoch.
  int get timestamp => RustLib.instance.api
      .kosherRustCalendarMoladFrbOverrideTimestamp(that: this);

  /// The day of the week, counting from midnight, 1 for Monday through 7 for Sunday.
  int get weekday => RustLib.instance.api
      .kosherRustCalendarMoladFrbOverrideWeekday(that: this);
}

@sealed
class MyZmanimCalculatorImpl extends RustOpaque implements MyZmanimCalculator {
  // Not to be used by end users
  MyZmanimCalculatorImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  MyZmanimCalculatorImpl.frbInternalSseDecode(
    BigInt ptr,
    int externalSizeOnNative,
  ) : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_MyZmanimCalculator,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_MyZmanimCalculator,
    rustArcDecrementStrongCountPtr: RustLib
        .instance
        .api
        .rust_arc_decrement_strong_count_MyZmanimCalculatorPtr,
  );

  /// How long before sunset candles are lit.
  Duration get candleLightingOffset => RustLib.instance.api
      .crateApiZmanimMyZmanimCalculatorCandleLightingOffset(that: this);

  /// The date.
  GregorianDate get date =>
      RustLib.instance.api.crateApiZmanimMyZmanimCalculatorDate(that: this);

  /// The time of `zman` on this day, in seconds since the Unix epoch.
  ///
  /// Throws `ZmanimException.allDay` or `allNight` where the website shows no time, because the sun
  /// never reaches the angle this time, or one it is built from, needs. Throws
  /// `timeZoneRequired` when there is no time zone and the location is more than 150° from
  /// Greenwich, and `invalidOffset` for candle lighting when its offset is a day or more.
  Future<int> time({required MyZman zman}) => RustLib.instance.api
      .crateApiZmanimMyZmanimCalculatorGet(that: this, zman: zman);

  /// A twelfth of the day from level sunrise to level sunset, the proportional hour of the Gra
  /// and the Baal HaTanya.
  ///
  /// It is not rounded. The proportional times, such as `MyZman.shemaGra`, round sunrise and
  /// sunset to the nearest second first, so adding these hours to sunrise can differ from them
  /// by up to a second.
  ///
  /// Throws `ZmanimException.allDay` or `allNight` when the sun doesn't rise or set.
  Future<Duration> proportionalHourGra() => RustLib.instance.api
      .crateApiZmanimMyZmanimCalculatorProportionalHourGra(that: this);
}

